#include <stdio.h>

int main(void) {
  int arr[5] = {10, 20, 30, 40, 50};
  int *p = arr;
  int sum = 0;

  for (int i = 0; i < 5; i++) {
    if (i % 2 == 0) {
      sum += *(p + i);
    } else {
      sum -= *(p + i);
    }
  }

  printf("%d\n", sum);
  printf("%d\n", *p + *(p + 4));

  return 0;
}

